```python
import csv
from typing import Dict, List, Union

def calculate_column_averages(csv_file_path: str) -> Dict[str, float]:
    """
    读取CSV文件并计算每列数值的平均值。

    参数:
        csv_file_path (str): CSV文件的路径

    返回:
        Dict[str, float]: 键为列名，值为该列平均值的字典

    异常:
        FileNotFoundError: 如果文件不存在
        ValueError: 如果CSV文件为空或没有数值列
    """
    try:
        with open(csv_file_path, 'r', encoding='utf-8') as file:
            reader = csv.DictReader(file)

            if reader.fieldnames is None:
                raise ValueError("CSV文件为空")

            # 初始化存储每列数据的字典
            column_data: Dict[str, List[float]] = {col: [] for col in reader.fieldnames}

            for row in reader:
                for col_name in reader.fieldnames:
                    value_str = row[col_name].strip()

                    # 尝试将值转换为浮点数
                    try:
                        value = float(value_str)
                        column_data[col_name].append(value)
                    except ValueError:
                        # 跳过非数值数据
                        continue

            # 计算每列的平均值
            averages: Dict[str, float] = {}
            for col_name, values in column_data.items():
                if not values:
                    averages[col_name] = 0.0  # 如果没有数值数据，平均值为0
                else:
                    averages[col_name] = sum(values) / len(values)

            return averages

    except FileNotFoundError:
        raise FileNotFoundError(f"找不到文件: {csv_file_path}")
    except PermissionError:
        raise PermissionError(f"没有权限读取文件: {csv_file_path}")

# 使用示例
if __name__ == "__main__":
    # 示例CSV文件内容：
    # name,age,score
    # Alice,25,85.5
    # Bob,30,92.3
    # Charlie,22,78.0

    try:
        result = calculate_column_averages("data.csv")
        print("每列平均值:")
        for column, avg in result.items():
            print(f"{column}: {avg:.2f}")
    except Exception as e:
        print(f"错误: {e}")
```

这个函数具有以下特点：

1. **类型提示**：使用类型注解提高代码可读性
2. **错误处理**：处理文件不存在、权限问题和空文件等情况
3. **灵活性**：自动跳过非数值数据，只计算数值列的平均值
4. **编码支持**：使用UTF-8编码读取文件
5. **文档完善**：包含详细的文档字符串说明

