```python
import csv
from typing import Dict

def simple_column_averages(csv_file_path: str) -> Dict[str, float]:
    """简化版：读取CSV并计算每列平均值"""
    with open(csv_file_path, 'r') as file:
        reader = csv.DictReader(file)
        sums = {col: 0.0 for col in reader.fieldnames}
        counts = {col: 0 for col in reader.fieldnames}

        for row in reader:
            for col in reader.fieldnames:
                try:
                    sums[col] += float(row[col])
                    counts[col] += 1
                except ValueError:
                    continue

        return {col: sums[col] / counts[col] if counts[col] > 0 else 0.0 
                for col in reader.fieldnames}
```

